//! A tiny mod built entirely from Rust code.
//!
//! Run with:
//!
//! ```text
//! cargo run -p hello-mod
//! ```
//!
//! Set `RIMWORLD_DIR` to point at a RimWorld 1.6 install (or pass
//! `.game_dir(...)`); otherwise common GOG/Steam locations are probed.

use std::path::PathBuf;

use rim_rs::prelude::*;

/// C# generated by another tool (or written by hand) and passed in verbatim.
const MOD_CODE: &str = r#"using RimWorld;
using Verse;

[StaticConstructorOnStartup]
public static class RimRsTestMod
{
    static RimRsTestMod()
    {
        Log.Message("[rim-rs] test mod loaded");

        ThingDef thing = DefDatabase<ThingDef>.GetNamedSilentFail("RimRsPurpleCube");
        if (thing != null)
        {
            Log.Message("[rim-rs] thing loaded: " + thing.defName + " / " + thing.label);
            Log.Message("[rim-rs] flammability: " + thing.GetStatValueAbstract(StatDefOf.Flammability));
        }
        else
        {
            Log.Error("[rim-rs] thing missing: RimRsPurpleCube");
        }

        RecipeDef recipe = DefDatabase<RecipeDef>.GetNamedSilentFail("Make_RimRsPurpleCube");
        if (recipe != null)
        {
            Log.Message("[rim-rs] recipe loaded: " + recipe.defName);
            if (DefDatabase<ThingDef>.GetNamed("CraftingSpot").AllRecipes.Contains(recipe))
                Log.Message("[rim-rs] recipe attached to CraftingSpot");
            else
                Log.Error("[rim-rs] recipe not attached to CraftingSpot");
        }
        else
        {
            Log.Error("[rim-rs] recipe missing: Make_RimRsPurpleCube");
        }
    }
}
"#;

fn main() -> Result<()> {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));

    let report = Mod::builder("Rim RS Test")
        .package_id("miquella.rimrstest")
        .author("miquella")
        .description(
            "A test mod generated by rim-rs: one resource, one recipe, one C# entry point.",
        )
        .url("https://example.invalid/rim-rs")
        .supported_versions(["1.6"])
        .defs(|defs| {
            defs.file("RimRsItems", |file| {
                file.add(
                    ThingDef::new("RimRsPurpleCube")
                        .parent("ResourceBase")
                        .label("rim-rs purple cube")
                        .description(
                            "A purple cube produced as a test of the <b>rim-rs</b> builder. \
                             It exists mostly to prove that text & markup survive the pipeline.",
                        )
                        .texture("Things/Item/RimRsPurpleCube")
                        .stack_limit(75)
                        .hit_points(100)
                        .market_value(42)
                        .mass(0.5)
                        .child(Element::new("thingCategories").child_text("li", "Manufactured")),
                );
            });

            defs.file("RimRsRecipes", |file| {
                file.add(
                    RecipeDef::new("Make_RimRsPurpleCube")
                        .label("make a rim-rs purple cube")
                        .description("Shape steel into a suspiciously purple cube.")
                        .job_string("Making a rim-rs purple cube.")
                        .work_amount(400.0)
                        .work_speed_stat("GeneralLaborSpeed")
                        .work_skill("Crafting")
                        .ingredient("Steel", 20)
                        .product("RimRsPurpleCube", 1)
                        .recipe_user("CraftingSpot"),
                );
            });
        })
        .patches(|patches| {
            patches.add(Patch::new("RimRsTweak").op("PatchOperationAdd", |op| {
                op.xpath(r#"Defs/ThingDef[defName="RimRsPurpleCube"]/statBases"#)
                    .raw_value("<Flammability>0.4</Flammability>");
            }));
        })
        .csharp("RimRsTestMod.cs", MOD_CODE)
        .assets(|assets| {
            assets.textures(root.join("assets/textures"));
            assets.preview(root.join("assets/preview.png"));
        })
        .options(BuildOptions::default().base_dir(&root))
        .build()?;

    println!("mod dir: {}", report.mod_dir.display());
    if let Some(dll) = &report.dll_path {
        println!("dll:     {}", dll.display());
    }
    if let Some(zip) = &report.zip_path {
        println!("zip:     {}", zip.display());
    }

    Ok(())
}
